"""Build auditable claim records from fetched public artifacts, not search snippets."""
import collections,datetime,hashlib,json,pathlib
R=pathlib.Path(__file__).resolve().parent
logs=json.loads((R/'fetch-log.json').read_text()); latest={x['key']:x for x in logs}
claims=[]
def add(cid,model,claim,keys,section,status,scope,placement,notes=''):
 sources=[latest[k] for k in keys]
 assert all(s.get('status')==200 for s in sources),(cid,keys)
 claims.append({'id':cid,'claim':claim,'exact_model_id':model,'source_url':sources[0]['url'],'additional_source_urls':[s['url'] for s in sources[1:]],'retrieved_date':sources[0]['retrieved_at'][:10],'retrieved_at':[s['retrieved_at'] for s in sources],'section':section,'evidence_status':status,'benchmark_scope':scope,'proposed_chapter_placement':placement,'source_keys':keys,'local_evidence':[{'path':s['local_path'],'sha256':s['sha256']} for s in sources],'notes':notes})
