index=[]
for key,s in latest.items():
 entry=dict(s);entry['citation_key']=key
 if s.get('status')==200:
  path=R/s['local_path'];entry['local_sha256_matches']=hashlib.sha256(path.read_bytes()).hexdigest()==s['sha256']
 index.append(entry)
(R/'source-index.json').write_text(json.dumps(index,ensure_ascii=False,indent=2)+'\n')
calc={'qwen27_bf16_full_attention_kv_bytes_per_token':2*16*4*256*2,'qwen27_context_tokens':262144,'qwen27_bf16_full_attention_kv_bytes_at_native_context':2*16*4*256*2*262144,'qwen27_bf16_full_attention_kv_GiB_at_native_context':2*16*4*256*2*262144/2**30,'qwen27_config_layers':collections.Counter(json.loads((R/'sources/qwen-config.txt').read_text())['text_config']['layer_types'])}
(R/'calculations.json').write_text(json.dumps(calc,indent=2)+'\n')
print(json.dumps({'claim_count':len(claims),'source_count':len(index),'source_fetch_success':sum(x.get('status')==200 for x in index),'hash_mismatch':[x['key'] for x in index if x.get('local_sha256_matches') is False],'evidence_status_counts':collections.Counter(x['evidence_status'] for x in claims),'calculations':calc},ensure_ascii=False,indent=2))
